import{_ as r}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as t}from"./chunks/ON.DXVlsWbj.js";import{_ as i}from"./chunks/OFF.BrU7kQE-.js";import{_ as s,a}from"./chunks/M-S-GMc.LRrwxYc0.js";import{_ as o}from"./chunks/DIS.DdpTdGGD.js";import{_ as n,o as l,c as u,a3 as c}from"./chunks/framework.g9mfNVRQ.js";const C=JSON.parse('{"title":"Lecteur de glycémie","description":"","frontmatter":{"source_hash":"ec52e7eb65","source_commit":"7a18e7c"},"headers":[],"relativePath":"fr/use/glucometer.md","filePath":"fr/use/glucometer.md"}'),p={name:"fr/use/glucometer.md"};function m(d,e,v,h,_,g){return l(),u("div",null,[...e[0]||(e[0]=[c('<div class="admonition xdrip"><p class="admonition-title"><img src="'+r+'" style="zoom:75%;"></p><p> Paramètres<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_touch_app_grey600_48dp.png" style="width:5%;"> Lecteurs de Glycémie</p></div><br><h5 id="nfc-meter" tabindex="-1">Lecteur NFC <a class="header-anchor" href="#nfc-meter" aria-label="Permalink to &quot;Lecteur NFC {#nfc-meter}&quot;">​</a></h5><p>Si vous utilisez un lecteur Glucomen Aero avec un téléphone équipé d&#39;un lecteur NFC, vous pouvez le scanner pour récupérer la dernière mesure.</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser le lecteur NFC <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Télécharger les enregistrements de glucose à partir du lecteur NFC lorsque xDrip est ouvert</p></div><h5 id="if-you-use-a-compatible-bluetooth-meter" tabindex="-1">Si vous utilisez un lecteur Bluetooth compatible <a class="header-anchor" href="#if-you-use-a-compatible-bluetooth-meter" aria-label="Permalink to &quot;Si vous utilisez un lecteur Bluetooth compatible {#if-you-use-a-compatible-bluetooth-meter}&quot;">​</a></h5><p>Pour pouvoir activer Utiliser un lecteur Bluetooth, vous devez d&#39;abord appairer un lecteur Bluetooth.<br> S&#39;il s&#39;agit d&#39;un lecteur neuf, <strong>assurez-vous d&#39;avoir mesuré votre glycémie au moins une fois avant d&#39;essayer de l&#39;appairer</strong>.</p><p><strong><u>N&#39;activez pas</u></strong> encore l&#39;option de lecteur Bluetooth dans xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser un lecteur Bluetooth <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Automatiquement connecter et extraire des données d&#39;un lecteur de glycémie compatible standard comme le Contour Next One</p></div><p>Recherche du lecteur Bluetooth :</p><div class="admonition xdripitem"><p class="admonition-title">Scanner pour trouver un lecteur Bluetooth</p></div><p>Mettez votre lecteur en mode appairage et appuyez sur Balayage dans le menu Scanner pour trouver un lecteur Bluetooth.</p><img src="'+s+'" style="zoom:75%;"><img src="'+a+'" style="zoom:75%;"><p>Une fois l&#39;appairage effectué, vous pouvez activer le lecteur dans le menu.</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser un lecteur Bluetooth <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Automatiquement connecter et extraire des données d&#39;un lecteur de glycémie compatible standard comme le Contour Next One</p></div><p>Votre lecteur s&#39;affiche maintenant en dessous :</p><div class="admonition xdripitem"><p class="admonition-title">Scanner pour trouver un lecteur Bluetooth</p><p> Bayer HealthCare LLC AA:BB:CC:DD:EE:FF:00</p></div><p>Vous pouvez activer des sons pour signaler la connexion, la déconnexion et la récupération des données.</p><div class="admonition xdripitem"><p class="admonition-title">Indicateurs d’effets sonores</p><p> Cocher pour jouer des effets sonores lorsque le compteur se connecte, se déconnecte ou synchronise les données</p></div><p>xDrip peut vous proposer d&#39;utiliser le résultat pour étalonner votre capteur connecté (s&#39;il accepte l&#39;étalonnage).</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser Meter pour les Calibrations <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Lorsqu&#39;une nouvelle glycémie est reçue, demander si elle doit être utilisée pour calibrer</p></div><p>Il n&#39;est pas recommandé d&#39;activer l&#39;étalonnage automatique.</p><div class="admonition xdripitem"><p class="admonition-title">Calibration automatique <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Calibrer en utilisant de nouvelles lectures de glycémie si les conditions semblent correctes sans demander confirmation (expérimental)</p></div><p>Lorsque vous activez l&#39;utilisation du lecteur Bluetooth, toutes les glycémies capillaires sont automatiquement transférées dans xDrip en tant que <a href="./mainUI.html#treatments">traitements</a>.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2022.05.04" target="_blank" rel="noreferrer"><em>Dernière modification le 4/5/2022</em></a></p>',27)])])}const q=n(p,[["render",m]]);export{C as __pageData,q as default};
